metrics.workdir_dsl:
workspace "Bookshop" "A simple online bookshop" {
    configuration {
        scope softwaresystem
    }

    model {
        customer = person "Customer" "A customer who browses and buys books"

        bookshop = softwareSystem "Bookshop" "An online bookshop for browsing, ordering and paying for books" {
            catalogue = container "Catalogue" "Lets customers browse and search the book catalogue" "Java / Spring Boot"
            basket = container "Basket" "Holds the books a customer has selected for purchase" "Java / Spring Boot"
            orders = container "Orders" "Records orders and tracks their fulfilment" "Java / Spring Boot"
            database = container "Database" "Stores books, baskets and orders" "PostgreSQL 16"
        }

        payments = softwareSystem "Payment Gateway" "A third-party service that authorises and captures card payments"

        customer -> bookshop "Browses books and places orders" "HTTPS"
        bookshop -> payments "Submits card charges" "HTTPS/REST"
        catalogue -> database "Reads book data" "JDBC"
        basket -> database "Reads and writes basket data" "JDBC"
        orders -> database "Writes order data" "JDBC"
    }

    views {
        systemContext bookshop "SystemContext" "Shows who uses the Bookshop and the external systems it depends on" {
            include *
            autoLayout
        }

        container bookshop "Containers" "Shows the main containers inside the Bookshop" {
            include *
            autoLayout
        }

        theme default
    }
}
